请对以下 case 进行三维加权评分。

=== case_id ===
Case-15-smart-home-014

=== 用户原始指令 (query.txt) ===
智能家居状态卡，卡片表面简洁素净，上方放大的主信息（大号字），下方一个明确点击按钮。固定文案+系统开关切换（省电或勿扰），读取日历日程数据，时间/夜晚渐变背景，文字字符图标，含"已完成"或"已连接"正向状态，横向重复排列几项。

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "智能家居状态卡，卡片表面简洁素净，上方放大的主信息（大号字），下方一个明确点击按钮。固定文案+系统开关切换（省电或勿扰），读取日历日程数据，时间/夜晚渐变背景，文字字符图标，含\"已完成\"或\"已连接\"正向状态，横向重复排列几项。",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToIntent",
      "args": {
        "intentName": "SetSettingSwitch",
        "params": {
          "appBundleName": "com.huawei.hmos.settings",
          "itemName": "battery_saving_mode",
          "switchFlag": 0
        }
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "calendar": {
        "items": {
          "type": "array",
          "description": "今天的本地日历日程列表，用于横向展示少量日程摘要。",
          "sampleValue": [
            {
              "entityId": "calendar-home-001",
              "title": "回家场景",
              "dtStart": "19:30",
              "dtEnd": "20:00"
            },
            {
              "entityId": "calendar-home-002",
              "title": "夜间巡检",
              "dtStart": "21:00",
              "dtEnd": "21:10"
            }
          ],
          "items": {
            "type": "object",
            "description": "单条日程项。",
            "properties": {
              "entityId": {
                "type": "string",
                "description": "日程唯一标识符。",
                "sampleValue": "calendar-home-001"
              },
              "title": {
                "type": "string",
                "description": "日程标题。",
                "sampleValue": "回家场景"
              },
              "dtStart": {
                "type": "string",
                "description": "日程开始时间，当天日程为 HH:MM 格式。",
                "sampleValue": "19:30"
              },
              "dtEnd": {
                "type": "string",
                "description": "日程结束时间，当天日程为 HH:MM 格式。",
                "sampleValue": "20:00"
              }
            }
          }
        }
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/house_fill.svg",
      "description": "房屋实心图标，适合智能家居入口或家庭状态识别。"
    },
    {
      "src": "resources/base/media/battery_leaf_fill.svg",
      "description": "电池与绿叶图标，适合省电模式、绿色用电或系统节能动作。"
    },
    {
      "src": "resources/base/media/calendar_fill.svg",
      "description": "日历图标，适合日程摘要、日历事件或当日安排。"
    }
  ]
}

